+	if !hasTokenUsageData(d.TokenUsage) {
+		return false
+	}
+	if d.TokenUsage.CostUSD == nil {
+		return true
+	}
+	for i := range d.ModelUsage {
+		if d.ModelUsage[i].Model == "" {
+			bucket := d.ModelUsage[i].TokenUsage
+			if hasTokenUsageData(&bucket) {
+				return true
+			}
+		}
+	}
+	return false
