+		fullUsage, _ := tokenUsageWithCost(ctx, ag, sessionData.Transcript, 0, state.ModelName, state.AgentType)
+		if hasTokenUsageData(fullUsage) {
+			state.TokenUsage = fullUsage
+		}
+	}
