+	table, err := pricing.LoadTable(overrides)
+	if err != nil {
+		logging.Warn(ctx, "pricing: table load failed; cost estimation unavailable",
+			slog.String("error", err.Error()))
+		return nil, disable
+	}
+	return table, disable
