+	models := make([]string, 0, len(byModel))
+	for m := range byModel {
+		models = append(models, m)
+	}
+	sort.Strings(models)
+
+	buckets := make([]agent.ModelUsage, 0, len(models))
+	for _, m := range models {
+		buckets = append(buckets, agent.ModelUsage{Model: m, TokenUsage: *byModel[m]})
+	}
+	return buckets, nil
+}
